const x = $input.first().json;
const toIso = (value, field) => {
  const v = String(value ?? '').trim();
  if (!v) return null;
  const withT = v.replace(/^(\d{4}-\d{2}-\d{2})\s+/, '$1T');
  const hasZone = /(Z|[+-]\d{2}:?\d{2})$/i.test(withT);
  const full = hasZone ? withT : (/^\d{4}-\d{2}-\d{2}$/.test(withT) ? withT + 'T00:00:00' : withT) + '+07:00';
  const t = Date.parse(full);
  if (Number.isNaN(t)) throw new Error('invalid_datetime: ' + field + '=' + v);
  return new Date(t).toISOString();
};
const parseJson = (value, field, fallback) => {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { throw new Error('invalid_json: ' + field); }
};
if (!String(x.finding_id || '').trim()) throw new Error('missing_information: finding_id');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(x.finding_id).trim())) throw new Error('finding_not_found: finding_id không phải uuid hợp lệ');
const start = toIso(x.cleanup_start_at, 'cleanup_start_at');
if (!start) throw new Error('missing_information: cleanup_start_at');
const end = toIso(x.cleanup_end_at, 'cleanup_end_at');
if (end && Date.parse(end) <= Date.parse(start)) throw new Error('invalid_datetime: cleanup_end_at phải sau cleanup_start_at');
const website = parseJson(x.website_payload, 'website_payload', null);
const threads = parseJson(x.threads_payload, 'threads_payload', null);
if (!website || typeof website !== 'object' || !String(website.title || '').trim()) throw new Error('invalid_payload: website_payload cần có title');
if (!threads || typeof threads !== 'object' || !String(threads.text || threads.content || '').trim()) throw new Error('invalid_payload: threads_payload cần có text');
if (String(threads.text || threads.content).length > 500) throw new Error('threads_text_too_long: tối đa 500 ký tự');
const images = parseJson(x.images, 'images', []);
const sources = parseJson(x.sources, 'sources', []);
if (!Array.isArray(images) || !Array.isArray(sources)) throw new Error('invalid_json: images và sources phải là array');
return [{ json: { ...x, cleanup_start_at: start, cleanup_end_at: end, meeting_point: x.meeting_point || null, contact: x.contact || null, website_payload: website, threads_payload: threads, images, sources } }];

const x = $('Validate Draft Input').first().json;
const finding = $input.first().json;
if (!finding.id) throw new Error('finding_not_found: finding_id không tồn tại hoặc không thuộc thread hiện tại. Hãy tìm lại bằng search_pollution_locations hoặc hỏi admin chọn địa điểm khác.');
return [{ json: x }];
